import os, json, re

RLM_SESSION_DIR = os.environ['RLM_SESSION_DIR']
fpath = os.path.join(RLM_SESSION_DIR, '../../sessions/01a181b0-1efb-75a9-8c54-96f9981b09c4.jsonl')

with open(fpath) as f:
    for line in f:
        try:
            data = json.loads(line)
            if 'Demo pair' in data:
                print("Found demo pair!")
                print(json.dumps(data, indent=2)[:1500])
                break
        except:
            pass

# List all diffs
diffs = []
in_grid = demo1_input
out_grid = demo1_output
H, W = len(in_grid), len(in_grid[0])
for r in range(H):
    for c in range(W):
        if in_grid[r][c] != out_grid[r][c]:
            diffs.append((r, c, in_grid[r][c], out_grid[r][c]))

print(f"Total {len(diffs)} diffs:")
for d in diffs:
    print(d)

# Now let me find ALL 3s in the output
output_3s = []
for r in range(H):
    for c in range(W):
        if out_grid[r][c] == 3:
            output_3s.append((r, c))

print(f"\nAll 3s in output ({len(output_3s)}):")
print(output_3s)

# Now let me look at the INPUT 3s (after removing duplicates)
input_3s = set()
for r in range(H):
    for c in range(W):
        if in_grid[r][c] == 3:
            input_3s.add((r, c))
print(f"\nAll 3s in input ({len(input_3s)}):")
print(input_3s)

# New 3s (in output but not in input)
new_3s = set(output_3s) - input_3s
print(f"\nNew 3s ({len(new_3s)}):")
print(new_3s)

# Let me search for patterns in missing 3s by analyzing which input 3s could explain them
# via "half-distance" or "chord" relationships

in_3s = set([(5, 5), (6, 3), (6, 4), (7, 3), (7, 4), (8, 3)])
missing = [(1, 11), (2, 9), (2, 10), (3, 9), (3, 10), (4, 9), (5, 7), (5, 8), 
           (6, 7), (6, 8), (7, 6), (7, 7), (8, 6), (10, 4), (10, 10)]

print("Testing chord hypothesis: for a 3 at (r,c), check if input has 3s at (r,c+1) or (r+1,c)...")
# Or more broadly: check if there's a relationship where output 3s are "between" input 3s

# Idea: For each pair of input 3s, mark the midpoint in output
chord_3s = set()
for (r1, c1) in in_3s:
    for (r2, c2) in in_3s:
        if (r1, c1) != (r2, c2):
            # Midpoint
            mr, mc = (r1 + r2) / 2, (c1 + c2) / 2
            if mr.is_integer() and mc.is_integer():
                chord_3s.add((int(mr), int(mc)))

print(f"Chord midpoints ({len(chord_3s)}): {sorted(chord_3s)}")
missing_set = set(missing)
print(f"Chord 3s in missing? {chord_3s & missing_set}")

# Test: output[r,c]=3 if input[r,c]=3, or input[r,c]=0 AND input[r,c+1]=3, or input[r,c]=0 AND input[c]==3 (same row)
row_adjacent = set()
for (r1, c1) in in_3s:
    # Check rows for adjacent 3s
    for c in range(c1+1, in_grid.shape[1]):
        if (r1, c) in in_3s:
            # 3s in same row
            for c2 in range(min(c1, c), max(c1, c)+1):
                if c2 not in (c1, c):
                    row_adjacent.add((r1, c2))
    # Check columns for adjacent 3s
    for r in range(r1+1, in_grid.shape[0]):
        if (r, c1) in in_3s:
            for r2 in range(min(r1, r), max(r1, r)+1):
                if r2 not in (r1, r):
                    row_adjacent.add((r2, c1))

print(f"Row/col adjacent 3s ({len(row_adjacent)}): {sorted(row_adjacent)}")
print(f"Are these in missing? {row_adjacent & missing_set}")

# Let me check if there's a "third half" rule
# Output 3s seem to follow: input[r+dr, c+dc]=3 for dr,dc odd pairs

in_3s = set([(5, 5), (6, 3), (6, 4), (7, 3), (7, 4), (8, 3)])

# Generate output 3s: for each input 3, we get positions at:
# 1. (r, c) identity
# 2. (r+1, c+1) diagonal
# 3. (r-1, c-1) anti-diagonal  
# 4. (r+1, c-1)
# 5. (r-1, c+1)
# And maybe more?

# Let me check: which of the 5 shifts do we see for each input 3?
for (r,c) in in_3s:
    shifts = []
    if (r, c) in set(output_3s): shifts.append("(r,c)")
    if (r+1, c+1) in set(output_3s): shifts.append("(r+1, c+1)")
    if (r-1, c-1) in set(output_3s): shifts.append("(r-1, c-1)")
    if (r+1, c-1) in set(output_3s): shifts.append("(r+1, c-1)")
    if (r-1, c+1) in set(output_3s): shifts.append("(r-1, c+1)")
    print(f"Input {r,c}: shifts -> {shifts}")

# Full generated output using 6 shifts:
# (r,c), (r+1,c+1), (r-1,c-1), (r+2,c+2), (r-2,c-2), and maybe diagonals

gen_full = set()
for (r,c) in in_3s:
    for dr in [-2, -1, 0, 1, 2]:
        for dc in [-2, -1, 0, 1, 2]:
            if dr == 0 and dc == 0: continue  # skip identity
            if (r+dr, c+dc) in set(output_3s):
                gen_full.add((r+dr, c+dc))

print(f"\nGenerated positions ({len(gen_full)}): {sorted(gen_full)}")
print(f"All output_3s? {gen_full & output_3s == output_3s}")

